This uses one postorder traversal. Every recursive call returns the subtree height and the distance to the start node when that node is inside the subtree. This lets the code check both directions of the fire without changing the input tree.

When the start is below the left child, the fire can reach the current node and then continue through the right subtree. The same check is done in the other direction.

```csharp
/*
 // Definition for a binary tree node.
 public class TreeNode {
     public int val;
     public TreeNode left;
     public TreeNode right;

     public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null) {
         this.val = val;
         this.left = left;
         this.right = right;
     }
 }
*/

public class Solution {
    private int answer;

    private class State {
        public int Height;
        public int Distance;

        public State(int height, int distance) {
            Height = height;
            Distance = distance;
        }
    }

    private State Visit(TreeNode node, int start) {
        if (node == null) {
            return new State(0, -1);
        }

        State left = Visit(node.left, start);
        State right = Visit(node.right, start);
        int height = 1 + System.Math.Max(left.Height, right.Height);
        int distance = -1;

        if (node.val == start) {
            distance = 0;
            answer = System.Math.Max(left.Height, right.Height);
        } else if (left.Distance != -1) {
            distance = left.Distance + 1;
            answer = System.Math.Max(answer, distance + right.Height);
        } else if (right.Distance != -1) {
            distance = right.Distance + 1;
            answer = System.Math.Max(answer, distance + left.Height);
        }

        return new State(height, distance);
    }

    public int TimeToBurnTree(TreeNode root, int start) {
        answer = 0;
        if (root == null) {
            return 0;
        }

        Visit(root, start);
        return answer;
    }
}
```

For a single-node tree, no edge needs to burn, so the result is 0. A start value that does not occur also leaves the result at 0.

Time complexity: O(n), with one visit per node.
Space complexity: O(h) for the recursive call stack, where h is the height of the tree.

I first store the parent of every node. After that, the tree can be treated like an undirected graph, so fire can move to the left child, right child, or parent.

A queue processes one burning layer at a time. The start node is marked before the search, which prevents moving back and forth forever.

```cpp
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int data;
 *     TreeNode *left;
 *     TreeNode *right;
 *      TreeNode(int val) : data(val) , left(nullptr) , right(nullptr) {}
 * };
 **/

class Solution{
public:
    int timeToBurnTree(TreeNode* root, int start){
        if (root == nullptr) {
            return 0;
        }

        unordered_map<TreeNode*, TreeNode*> parent;
        queue<TreeNode*> buildQueue;
        TreeNode* startNode = nullptr;

        buildQueue.push(root);
        parent[root] = nullptr;

        while (!buildQueue.empty()) {
            TreeNode* current = buildQueue.front();
            buildQueue.pop();

            if (current->data == start) {
                startNode = current;
            }

            if (current->left != nullptr) {
                parent[current->left] = current;
                buildQueue.push(current->left);
            }
            if (current->right != nullptr) {
                parent[current->right] = current;
                buildQueue.push(current->right);
            }
        }

        if (startNode == nullptr) {
            return 0;
        }

        queue<TreeNode*> burnQueue;
        unordered_set<TreeNode*> visited;
        burnQueue.push(startNode);
        visited.insert(startNode);
        int minutes = -1;

        while (!burnQueue.empty()) {
            int count = burnQueue.size();
            minutes++;

            while (count-- > 0) {
                TreeNode* current = burnQueue.front();
                burnQueue.pop();

                TreeNode* nextNodes[3] = {
                    current->left,
                    current->right,
                    parent[current]
                };

                for (TreeNode* next : nextNodes) {
                    if (next != nullptr && !visited.count(next)) {
                        visited.insert(next);
                        burnQueue.push(next);
                    }
                }
            }
        }

        return minutes;
    }
};
```

For example, if the start is a leaf, its parent burns after one minute, then the next level burns after two minutes. The returned value is the number of completed layers after the start layer.

Time complexity: O(n), where n is the number of nodes.
Space complexity: O(n) for the parent map, queue, and visited set.

The recursive version keeps two pieces of information for every subtree: its height and the distance from the current node to the start node. When the start is found, the answer can spread down through that subtree. When an ancestor is found, the fire can also move into the other subtree.

The height is measured in nodes, while the answer is measured in edges, so the formulas stay small and avoid another tree traversal.

```java
/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int data;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int val) { data = val; left = null, right = null }
 * }
 **/

class Solution {
    private int answer = 0;

    private static class Info {
        int height;
        int distance;

        Info(int height, int distance) {
            this.height = height;
            this.distance = distance;
        }
    }

    private Info dfs(TreeNode node, int start) {
        if (node == null) {
            return new Info(0, -1);
        }

        Info left = dfs(node.left, start);
        Info right = dfs(node.right, start);

        int height = 1 + Math.max(left.height, right.height);
        int distance = -1;

        if (node.data == start) {
            distance = 0;
            answer = Math.max(left.height, right.height);
        } else if (left.distance != -1) {
            distance = left.distance + 1;
            answer = Math.max(answer, distance + right.height);
        } else if (right.distance != -1) {
            distance = right.distance + 1;
            answer = Math.max(answer, distance + left.height);
        }

        return new Info(height, distance);
    }

    public int timeToBurnTree(TreeNode root, int start) {
        answer = 0;
        if (root == null) {
            return 0;
        }

        dfs(root, start);
        return answer;
    }
}
```

A tree with only the start node returns 0. If the given value is not present, the traversal leaves the answer at 0.

Time complexity: O(n), because each node is visited once.
Space complexity: O(h) for recursion, where h is the tree height.

Here the first pass finds the parent of each node and saves the node whose value equals `start`. The second pass burns the tree level by level. At each minute, the fire tries the left child, right child, and parent.

Using a `Set` is important because parent links make the structure look like a graph. Without it, the fire would keep returning to the node it just left.

```javascript
/**
 * Definition for a binary tree node.
 * class TreeNode {
 *      constructor(val = 0, left = null, right = null){
 *          this.data = val;
 *          this.left = null;
 *          this.right = null;
 *      }
 * }
 **/

class Solution {
    timeToBurnTree(root, start) {
        if (root === null) {
            return 0;
        }

        const parent = new Map();
        const stack = [root];
        let startNode = null;
        parent.set(root, null);

        while (stack.length > 0) {
            const node = stack.pop();

            if (node.data === start) {
                startNode = node;
            }

            if (node.left !== null) {
                parent.set(node.left, node);
                stack.push(node.left);
            }

            if (node.right !== null) {
                parent.set(node.right, node);
                stack.push(node.right);
            }
        }

        if (startNode === null) {
            return 0;
        }

        const queue = [startNode];
        const visited = new Set([startNode]);
        let head = 0;
        let minutes = -1;

        while (head < queue.length) {
            const levelSize = queue.length - head;
            minutes++;

            for (let i = 0; i < levelSize; i++) {
                const node = queue[head++];
                const neighbors = [node.left, node.right, parent.get(node)];

                for (const next of neighbors) {
                    if (next !== null && next !== undefined && !visited.has(next)) {
                        visited.add(next);
                        queue.push(next);
                    }
                }
            }
        }

        return minutes;
    }
}
```

A root start value works without any special change. Its children are processed in the next level, and the result is 0 when the root is also a leaf.

Time complexity: O(n), including the parent-building pass and the burn pass.
Space complexity: O(n).

