class Solution {
   public:
    void findParent(TreeNode* root,
                    unordered_map<TreeNode*, TreeNode*>& parent) {
        if (!root) return;
        if (root->left) {
            parent[root->left] = root;
            findParent(root->left, parent);
        }
        if (root->right) {
            parent[root->right] = root;
            findParent(root->right, parent);
        }
    }

    TreeNode* find(TreeNode* root, int start) {
        if (!root || start == root->data) return root;
        TreeNode* leftSearch = find(root->left, start);
        if (leftSearch) return leftSearch;
        return find(root->right, start);
    }
    int brute(TreeNode* root, int start) {
        // your code goes here

        // Overal TC : O(3*N) , SC : O(4*N)

        // parentMap O(N) time and o(N) space
        unordered_map<TreeNode*, TreeNode*> parent;
        findParent(root, parent);

        // TC : O(N) & stackspace O(N)
        TreeNode* startNode = find(root, start);

        if (!startNode) return 0;

        int time = 0;

        // TC : O(N) , SC : O(N+N) for que and hashmap

        queue<TreeNode*> q;
        q.push(startNode);

        unordered_map<TreeNode*, bool> burnt;
        burnt[startNode] = true;
        while (!q.empty()) {
            int n = q.size();
            for (int i = 0; i < n; i++) {
                auto node = q.front();
                q.pop();

                if (node->left && !burnt[node->left]) {
                    burnt[node->left] = true;
                    q.push(node->left);
                }

                if (node->right && !burnt[node->right]) {
                    burnt[node->right] = true;
                    q.push(node->right);
                }

                if (parent[node] && !burnt[parent[node]]) {
                    burnt[parent[node]] = true;
                    q.push(parent[node]);
                }
            }
            if (q.size()) time++;
        }
        return time;
    }
    TreeNode* findParentandTarget(int start, TreeNode* root,
                                  unordered_map<TreeNode*, TreeNode*>& parent) {
        queue<TreeNode*> q;
        q.push(root);
        TreeNode* startNode = nullptr;
        while (!q.empty()) {
            auto node = q.front();
            q.pop();
            if (node->data == start) startNode = node;
            if (node->left) {
                parent[node->left] = node;
                q.push(node->left);
            }
            if (node->right) {
                parent[node->right] = node;
                q.push(node->right);
            }
        }
        return startNode;
    }
    int better(TreeNode* root, int start) {
        // TC : O(N+N) , SC : O(N+N+N) for que and parent and burnt
        unordered_map<TreeNode*, TreeNode*> parent;
        TreeNode* startNode = findParentandTarget(start, root, parent);
        if (!startNode) return 0;
        int time = 0;
        queue<TreeNode*> q;
        q.push(startNode);
        unordered_set<TreeNode*> burnt;
        burnt.insert(startNode);
        while (!q.empty()) {
            int n = q.size();
            bool fireCrossed = false;
            for (int i = 0; i < n; i++) {
                auto node = q.front();
                q.pop();

                if (node->left && burnt.find(node->left) == burnt.end()) {
                    burnt.insert(node->left);
                    q.push(node->left);
                    fireCrossed = true;
                }

                if (node->right && burnt.find(node->right) == burnt.end()) {
                    burnt.insert(node->right);
                    q.push(node->right);
                    fireCrossed = true;
                }

                if (parent[node] && burnt.find(parent[node]) == burnt.end()) {
                    burnt.insert(parent[node]);
                    q.push(parent[node]);
                    fireCrossed = true;
                }
            }
            if (fireCrossed) time++;
        }
        return time;
    }
    int dfs(TreeNode* root, int start, int& min_time) {
        if (!root) return 0;
        int leftHeight = dfs(root->left, start, min_time);
        int rightHeight = dfs(root->right, start, min_time);

        if (root->data == start) {
            min_time = max({min_time, leftHeight, rightHeight});
            return -1;
        }

        if (leftHeight < 0) {
            // left subtree was burning
            int disToStart = abs(leftHeight);
            min_time = max(min_time, disToStart + rightHeight);

            return leftHeight - 1;
        }

        if (rightHeight < 0) {
            int disToStart = abs(rightHeight);
            min_time = max(min_time, disToStart + leftHeight);
            return rightHeight - 1;
        }

        return max(leftHeight, rightHeight) + 1;
    }
    int optimal(TreeNode* root, int start) {
        // Tc : O(N) each node visited once , SC : O(H) stack space , O(N) in worst case.
        int min_time = 0;
        dfs(root, start, min_time);
        return min_time;
    }
    int timeToBurnTree(TreeNode* root, int start) {
        return optimal(root, start);
        return better(root, start);
        return brute(root, start);
    }
};
