```java
/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int data;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int val) { data = val; left = null, right = null }
 * }
 **/

class Solution {
    public int timeToBurnTree(TreeNode root, int start) {
        HashMap<TreeNode, TreeNode> parents = new HashMap<>();
        TreeNode target = null;

        LinkedList<TreeNode> queue = new LinkedList<>();
        queue.add(root);
        parents.put(root, null);
        while(!queue.isEmpty()){
            TreeNode curr = queue.remove();
            if(curr.data == start) target=curr;
            if(curr.left != null){
                parents.put(curr.left, curr);
                queue.add(curr.left);
            }
            if(curr.right != null){
                parents.put(curr.right, curr);
                queue.add(curr.right);
            }
        }

        queue.add(target);
        int size=queue.size();
        int sec=0;
        HashSet<TreeNode> burned = new HashSet<>();
        burned.add(target);
        while(!queue.isEmpty()){
            TreeNode curr = queue.remove();
            size--;
            if(curr.left != null && !burned.contains(curr.left)){
                queue.add(curr.left);
                burned.add(curr.left);
            }
            if(curr.right != null && !burned.contains(curr.right)){
                queue.add(curr.right);
                burned.add(curr.right);
            }
            TreeNode parent = parents.get(curr);
            if(parent != null && !burned.contains(parent)){
                queue.add(parent);
                burned.add(parent);
            }
            if(size == 0){
                sec++;
                size=queue.size();
            }
        }
        return sec-1;
    }
}
